            if (CullNegativeXAxisMovement && components.X < 0.0f)
                components.X = 0.0f;
            if (CullAllYAxisMovement)
                components.Y = 0.0f;
            movement_delta = x_axis * components.X + y_axis * components.Y + z_axis * components.Z;
        }
    }
}

